class Logger
{
    unordered_map<string, int> lastPrinted;
public:
    Logger() {}
    bool shouldPrintMessage(int timestamp, string message)
    {
        auto it = lastPrinted.find(message);
        if (it != lastPrinted.end() && timestamp - it->second < 10)
        {
            return false;
        }
        lastPrinted[message] = timestamp;
        return true;
    }
};
